    [Fact]
    public void RecoveryValidatorRejectsNegativePlayerViewRowMetadata()
    {
        var playerViews = new Dictionary<string, RecoveredPlayerView>(StringComparer.Ordinal)
        {
            ["alice"] = PlayerView("alice", 0, 0) with
