    [Fact]
    public void RecoveryValidatorRejectsSnapshotTimingTriggerQueueOrderPromptFieldAbsenceDrift()
    {
        var alice = PlayerView("alice", 0, 0);
        var timing = alice.Snapshot.Timing
            .ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        timing["orderingPlayerId"] = "alice";
        timing["orderedTriggerIds"] = new[] { "trigger-1" };
        timing["triggerIds"] = new[] { "trigger-1" };
        timing["triggers"] = Array.Empty<object?>();
        timing["triggerChoices"] = Array.Empty<object?>();
        timing["legalOrderingConstraints"] = new Dictionary<string, object?>(StringComparer.Ordinal)
        {
            ["orderingPolicy"] = "APNAP_CONTROLLER_BLOCKS_CONSERVATIVE"
        };
        timing["triggeredByEventKind"] = "OBJECT_DESTROYED";
        timing["orderingState"] = "PENDING_ORDER";
        var playerViews = new Dictionary<string, RecoveredPlayerView>(StringComparer.Ordinal)
        {
            ["alice"] = alice with
            {
                Snapshot = alice.Snapshot with
                {
                    Timing = timing
                }
            }
        };

        var errors = MatchRecoveryValidator.Validate("room-a", 0, [], [], playerViews);

        Assert.Equal(
            8,
            errors.Count(error => error.Contains(
                "snapshot for alice timing order-trigger prompt field",
                StringComparison.Ordinal)));
        Assert.Contains(
            errors,
            error => error.Contains(
                "snapshot for alice timing order-trigger prompt field orderingPlayerId must be absent",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "snapshot for alice timing order-trigger prompt field legalOrderingConstraints must be absent",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "snapshot for alice timing order-trigger prompt field orderingState must be absent",
                StringComparison.Ordinal));
    }

