                                ["battlefieldObjectId"] = " battlefield-a ",
                                ["zonePlayerId"] = " ",
                                ["cardNo"] = RawJson("[]"),
                                ["controllerId"] = " alice ",
                                ["status"] = " UNKNOWN ",
                                ["contested"] = "false",
                                ["scoredThisTurn"] = 1,
                                ["standbySlotCount"] = "zero",
                                ["faceDownStandbyCount"] = -1,
