                Snapshot = alice.Snapshot with
                {
                    Players = players,
                    Lanes = lanes,
                    Timing = timing
                }
            }
        };

        var errors = MatchRecoveryValidator.Validate("room-a", 0, [], [], playerViews);

        Assert.Contains(
            errors,
            error => error.Contains(
                "snapshot for alice timing battlefield task item kind START_SPELL_DUEL is required by battlefield state contest for battlefield object id battlefield-a",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "snapshot for alice timing battlefield task item kind START_BATTLE is not required by battlefield state contest for battlefield object id battlefield-b",
                StringComparison.Ordinal));

        static Dictionary<string, object?> SnapshotObjectPayload(string objectId)
        {
            return new Dictionary<string, object?>(StringComparer.Ordinal)
            {
                ["objectId"] = objectId,
                ["ownerId"] = "alice",
                ["controllerId"] = "alice",
                ["isFaceDown"] = false,
                ["tags"] = new[] { P6TokenFactoryCatalog.BattlefieldCardTag },
                ["untilEndOfTurnEffects"] = Array.Empty<string>(),
                ["location"] = new Dictionary<string, object?>(StringComparer.Ordinal)
                {
                    ["playerId"] = "alice",
                    ["zone"] = "BATTLEFIELD",
                    ["battlefieldObjectId"] = objectId
                }
            };
        }

        static Dictionary<string, object?> BattlefieldLanePayload(string battlefieldObjectId, bool contested)
        {
            return new Dictionary<string, object?>(StringComparer.Ordinal)
            {
                ["battlefieldObjectId"] = battlefieldObjectId,
