                    ["bob"] = Array.Empty<string>()
                },
                ["standbyObjectIds"] = Array.Empty<string>(),
                ["standbySlots"] = Array.Empty<object?>(),
                ["standbySlotCount"] = 0,
                ["faceDownStandbyCount"] = 0,
                ["hiddenStandbyCount"] = 0,
                ["scoredThisTurn"] = false,
