        var battlefieldObjectItems = Assert.IsAssignableFrom<IReadOnlyList<object?>>(lanes["battlefieldObjectIds"])
            .ToArray();
        battlefieldObjectItems[0] = RawJson("""
            {
                "playerId": "alice",
                "playerId": "alice",
                " objectId ": "battlefield-a",
                "": true,
                "objectId": "battlefield-a"
            }
