        lanes["battlefieldObjectIds"] = battlefieldObjectItems;

        var battlefieldItems = Assert.IsAssignableFrom<IReadOnlyList<object?>>(lanes["battlefields"])
            .ToArray();
        battlefieldItems[0] = RawJson("""
            {
                "battlefieldObjectId": "battlefield-a",
                "battlefieldObjectId": "battlefield-a",
                " zonePlayerId ": "alice",
                "": true,
                "zonePlayerId": "alice",
