                        "slotId": "battlefield-a:standby:1",
                        " battlefieldObjectId ": "battlefield-a",
                        "": true,
                        "battlefieldObjectId": "battlefield-a",
                        "sidePlayerId": "alice",
                        "controllerId": "alice",
                        "visible": true,
                        "state": "VISIBLE",
                        "isFaceDown": false,
