                new StackItemState(
                    "stack-1",
                    "alice",
                    sourceObjectId: "spell-1",
                    effectKind: "DAMAGE",
                    cardNo: "SFD-001",
                    targetObjectIds: ["target-1"],
                    damageAmount: 2,
                    destination: "discard"),
                new StackItemState(
                    "stack-2",
                    "bob",
                    sourceObjectId: "spell-2",
                    effectKind: "DRAW",
                    cardNo: "SFD-002")
            ]);
        var events = new[]
        {
            RecoveredEvent(1, "TURN_ENDED"),
