                    cardNo: "SFD-001",
                    targetObjectIds: ["target-1"]),
                new StackItemState(
                    "stack-2",
                    "bob",
                    sourceObjectId: "spell-2",
                    effectKind: "DAMAGE",
                    cardNo: "SFD-002",
                    targetObjectIds: ["target-2"],
                    damageAmount: 3,
                    destination: "graveyard")
