        const string battlefieldObjectId = "alice-battlefield-card-1";
        const string visibleBattlefieldObjectId = "alice-visible-battlefield-1";
        var authoritativeState = new MatchState(
            "room-a",
            3,
            1,
            "alice",
            new Dictionary<string, string>(StringComparer.Ordinal)
            {
                ["alice"] = "P1",
                ["bob"] = "P2"
            },
            status: MatchStatuses.InProgress,
            readyPlayerIds: ["alice", "bob"],
            phase: MatchPhases.Main,
            timingState: TimingStates.NeutralOpen,
            playerZones: new Dictionary<string, PlayerZones>(StringComparer.Ordinal)
            {
                ["alice"] = PlayerZones.Empty with
                {
                    Battlefields = [visibleBattlefieldObjectId]
                },
                ["bob"] = PlayerZones.Empty
            },
            cardObjects: new Dictionary<string, CardObjectState>(StringComparer.Ordinal)
            {
                [battlefieldObjectId] = new(
                    battlefieldObjectId,
                    cardNo: "SFD-BATTLEFIELD",
                    ownerId: "alice",
                    controllerId: "alice"),
                [visibleBattlefieldObjectId] = new(
                    visibleBattlefieldObjectId,
                    power: 6,
                    tags: [CardObjectTags.UnitCard],
                    cardNo: "SFD-VISIBLE",
                    ownerId: "alice",
                    controllerId: "alice")
            },
            objectLocations: new Dictionary<string, ObjectLocationState>(StringComparer.Ordinal)
            {
                [visibleBattlefieldObjectId] = new("alice", "BATTLEFIELD", battlefieldObjectId)
            });
        var events = new[]
        {
            RecoveredEvent(1, "TURN_ENDED"),
            RecoveredEvent(2, "TURN_BEGAN")
        };
        var spectatorReplayFrame = MatchReplayRedactor.BuildSpectatorFrame(
            "room-a",
            3,
            2,
            events.Select(recoveredEvent => recoveredEvent.Event).ToArray(),
            authoritativeState);
        var players = spectatorReplayFrame.SpectatorSnapshot.Players.ToDictionary(
            entry => entry.Key,
            entry => entry.Value,
            StringComparer.Ordinal);
        var alicePayload = Assert.IsType<Dictionary<string, object?>>(players["alice"])
            .ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        var objects = Assert.IsType<Dictionary<string, object?>>(alicePayload["objects"])
            .ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        var visiblePayload = Assert.IsType<Dictionary<string, object?>>(objects[visibleBattlefieldObjectId])
            .ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        var visibleJson = JsonSerializer.Serialize(visiblePayload);
        alicePayload["objects"] = RawJson($$"""
            {
                "{{visibleBattlefieldObjectId}}": {{visibleJson}},
                "{{visibleBattlefieldObjectId}}": {{visibleJson}},
                " {{visibleBattlefieldObjectId}} ": {{visibleJson}},
                "": {}
            }
            """);
        players["alice"] = alicePayload;
        spectatorReplayFrame = spectatorReplayFrame with
        {
            SpectatorSnapshot = spectatorReplayFrame.SpectatorSnapshot with
            {
                Players = players
            }
        };

        var errors = MatchRecoveryValidator.Validate(
            "room-a",
            2,
            [],
            events,
            new Dictionary<string, RecoveredPlayerView>(StringComparer.Ordinal),
            authoritativeState,
            currentTick: 3,
            spectatorReplayFrame: spectatorReplayFrame);

        Assert.Contains(
            errors,
            error => error.Contains("spectator replay frame snapshot player alice objects property alice-visible-battlefield-1 appears more than once", StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains("spectator replay frame snapshot player alice objects property alice-visible-battlefield-1 has surrounding whitespace", StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains("spectator replay frame snapshot player alice objects property name is required", StringComparison.Ordinal));
    }

