                [otherParticipantObjectId] = new("bob", "BATTLEFIELD", battlefieldObjectId)
            });
        var events = new[]
        {
            RecoveredEvent(1, "TURN_ENDED"),
            RecoveredEvent(2, "TURN_BEGAN")
        };
        var spectatorReplayFrame = MatchReplayRedactor.BuildSpectatorFrame(
            "room-a",
            3,
            2,
            events.Select(recoveredEvent => recoveredEvent.Event).ToArray(),
            authoritativeState);
        var timing = spectatorReplayFrame.SpectatorSnapshot.Timing.ToDictionary(
            entry => entry.Key,
            entry => entry.Value,
            StringComparer.Ordinal);
        var battlefieldTasks = Assert.IsAssignableFrom<IEnumerable<object?>>(timing["battlefieldTasks"])
            .ToList();
        Assert.Equal(2, battlefieldTasks.Count);
        battlefieldTasks.Add(new Dictionary<string, object?>(StringComparer.Ordinal)
        {
            ["taskId"] = "task-extra-controller",
            ["kind"] = "START_BATTLE",
            ["status"] = "PENDING",
            ["reason"] = "SPELL_DUEL_AFTER_BATTLEFIELD_CONTEST",
            ["battlefieldObjectId"] = battlefieldObjectId,
            ["participantControllerIds"] = new[] { "alice", "bob" },
            ["participantObjectIds"] = new[] { participantObjectId },
            ["actingPlayerId"] = "alice",
            ["stackItemIds"] = Array.Empty<string>(),
            ["battleId"] = $"battle:{battlefieldObjectId}"
        });
        battlefieldTasks.Add(new Dictionary<string, object?>(StringComparer.Ordinal)
        {
            ["taskId"] = "task-missing-controller",
            ["kind"] = "START_BATTLE",
            ["status"] = "PENDING",
            ["reason"] = "SPELL_DUEL_AFTER_BATTLEFIELD_CONTEST",
            ["battlefieldObjectId"] = battlefieldObjectId,
            ["participantControllerIds"] = new[] { "alice" },
            ["participantObjectIds"] = new[] { participantObjectId, otherParticipantObjectId },
            ["actingPlayerId"] = "alice",
            ["stackItemIds"] = Array.Empty<string>(),
            ["battleId"] = $"battle:{battlefieldObjectId}"
        });
        timing["battlefieldTasks"] = battlefieldTasks.ToArray();
        spectatorReplayFrame = spectatorReplayFrame with
        {
            SpectatorSnapshot = spectatorReplayFrame.SpectatorSnapshot with
            {
                Timing = timing
            }
        };

        var errors = MatchRecoveryValidator.Validate(
            "room-a",
            2,
            [],
            events,
            new Dictionary<string, RecoveredPlayerView>(StringComparer.Ordinal),
            authoritativeState,
            currentTick: 3,
            spectatorReplayFrame: spectatorReplayFrame);

        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing battlefield task item participant controller id bob is not a controller for participant object ids; expected [alice] but got bob",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing battlefield task item participant controller id bob is required by participant object ids; expected contains bob but got [alice]",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing battlefield task count 4 does not match authoritative state battlefield task count 2",
                StringComparison.Ordinal));
    }

