        var firstTask = Assert.IsType<Dictionary<string, object?>>(tasks[0])
            .ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        var secondTask = Assert.IsType<Dictionary<string, object?>>(tasks[1])
            .ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        var originalFirstTaskId = Assert.IsType<string>(firstTask["taskId"]);
        var forgedTask = secondTask.ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
