            [],
            events,
            new Dictionary<string, RecoveredPlayerView>(StringComparer.Ordinal),
            authoritativeState,
            currentTick: 3,
            spectatorReplayFrame: spectatorReplayFrame);

        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing pending task queue task item task id forged-pending-task-a is not present in authoritative state pending task queue tasks",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing pending task queue task item task id forged-pending-task-b is not present in authoritative state pending task queue tasks",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                $"spectator replay frame timing pending task queue task item task id {originalFirstTaskId} is required by authoritative state pending task queue tasks",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing pending task queue task count does not match authoritative state pending task queue task count",
                StringComparison.Ordinal));
    }

