    [Fact]
    public void RecoveryValidatorRejectsSpectatorReplayTimingPendingPaymentMismatch()
    {
        var authoritativeState = new MatchState(
            "room-a",
            3,
            1,
            "alice",
            new Dictionary<string, string>(StringComparer.Ordinal)
            {
                ["alice"] = "P1",
                ["bob"] = "P2"
            },
            status: MatchStatuses.InProgress,
            readyPlayerIds: ["alice", "bob"],
            phase: MatchPhases.Main,
            timingState: TimingStates.NeutralOpen,
            pendingPayment: new PendingPaymentState(
                "payment-1",
                "PAY_COST",
                "alice",
                manaCost: 2,
                powerCost: 1,
                powerCostByTrait: new Dictionary<string, int>(StringComparer.Ordinal)
                {
                    ["blue"] = 1
                },
                legalPaymentChoiceIds: ["SPEND_MANA:2", "SPEND_POWER:1"],
                reason: "test-payment"));
        var events = new[]
        {
            RecoveredEvent(1, "TURN_ENDED"),
            RecoveredEvent(2, "TURN_BEGAN")
        };
        var spectatorReplayFrame = MatchReplayRedactor.BuildSpectatorFrame(
            "room-a",
            3,
            2,
            events.Select(recoveredEvent => recoveredEvent.Event).ToArray(),
            authoritativeState);
        var timing = spectatorReplayFrame.SpectatorSnapshot.Timing.ToDictionary(
            entry => entry.Key,
            entry => entry.Value,
            StringComparer.Ordinal);
        var pendingPayment = Assert.IsType<Dictionary<string, object?>>(timing["pendingPayment"])
            .ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        var cost = Assert.IsType<Dictionary<string, object?>>(pendingPayment["cost"])
            .ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        pendingPayment["paymentId"] = "wrong-payment";
        pendingPayment["paymentWindow"] = "WRONG_WINDOW";
        pendingPayment["playerId"] = "bob";
        cost["mana"] = 9;
        cost["power"] = 8;
        cost["powerByTrait"] = new Dictionary<string, object?>(StringComparer.Ordinal)
        {
            ["green"] = 2
        };
        pendingPayment["cost"] = cost;
        pendingPayment["paymentChoices"] = new[] { "SPEND_MANA:9" };
        timing["pendingPayment"] = pendingPayment;
        spectatorReplayFrame = spectatorReplayFrame with
        {
            SpectatorSnapshot = spectatorReplayFrame.SpectatorSnapshot with
            {
                Timing = timing
            }
        };

        var errors = MatchRecoveryValidator.Validate(
            "room-a",
            2,
            [],
            events,
            new Dictionary<string, RecoveredPlayerView>(StringComparer.Ordinal),
            authoritativeState,
            currentTick: 3,
            spectatorReplayFrame: spectatorReplayFrame);

        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing pending payment id does not match authoritative state pending payment id; expected payment-1 but got wrong-payment",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing pending payment window does not match authoritative state pending payment window; expected PAY_COST but got WRONG_WINDOW",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing pending payment player does not match authoritative state pending payment player; expected alice but got bob",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing pending payment mana cost does not match authoritative state pending payment mana cost; expected 2 but got 9",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing pending payment power cost does not match authoritative state pending payment power cost; expected 1 but got 8",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing pending payment power cost traits do not match authoritative state pending payment power cost traits; expected {blue: 1} but got {green: 2}",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing pending payment choices do not match authoritative state pending payment choices; expected [SPEND_MANA:2, SPEND_POWER:1] but got [SPEND_MANA:9]",
                StringComparison.Ordinal));
    }

    [Fact]
    public void RecoveryValidatorRejectsSpectatorReplayTimingPendingPaymentMissingPayloadWithoutCountMismatch()
    {
        var errors = ValidateSpectatorReplayTimingPendingPaymentPayload(
            EmptyPendingPaymentState(),
            removePayload: true);

        Assert.Contains(
            errors,
            error => error.Contains("spectator replay frame timing pending payment is required", StringComparison.Ordinal));
        Assert.DoesNotContain(
            errors,
