    [Fact]
    public void RecoveryValidatorRejectsSpectatorReplayTimingContinuousEffectKeyedDuplicateIdWithoutCountMismatch()
    {
        var authoritativeState = new MatchState(
            "room-a",
            3,
            1,
            "alice",
            new Dictionary<string, string>(StringComparer.Ordinal)
            {
                ["alice"] = "P1",
                ["bob"] = "P2"
            },
            status: MatchStatuses.InProgress,
            readyPlayerIds: ["alice", "bob"],
            phase: MatchPhases.Main,
            timingState: TimingStates.NeutralOpen,
            playerZones: new Dictionary<string, PlayerZones>(StringComparer.Ordinal)
            {
                ["alice"] = PlayerZones.Empty with
                {
                    Base = ["source-1", "target-1"]
                },
                ["bob"] = PlayerZones.Empty
            },
            cardObjects: new Dictionary<string, CardObjectState>(StringComparer.Ordinal)
            {
                ["source-1"] = new("source-1", ownerId: "alice", controllerId: "alice"),
                ["target-1"] = new(
                    "target-1",
                    power: 6,
                    untilEndOfTurnPowerModifier: 3,
                    ownerId: "alice",
                    controllerId: "alice",
                    untilEndOfTurnPowerModifiers:
                    [
                        new PowerModifierLedgerEntry(
                            "effect-1",
                            "TEST_POWER_MODIFIER",
                            "UNTIL_END_OF_TURN",
                            "target-1",
                            "source-1",
                            "SRC-001",
                            powerDelta: 2,
                            basePower: 3,
                            effectivePower: 5),
                        new PowerModifierLedgerEntry(
                            "effect-2",
                            "TEST_POWER_MODIFIER",
                            "UNTIL_END_OF_TURN",
                            "target-1",
                            "source-1",
                            "SRC-002",
                            powerDelta: 1,
                            basePower: 5,
                            effectivePower: 6)
                    ])
            },
            objectLocations: new Dictionary<string, ObjectLocationState>(StringComparer.Ordinal)
            {
                ["source-1"] = new("alice", "BASE"),
                ["target-1"] = new("alice", "BASE")
            });
        var events = new[]
        {
            RecoveredEvent(1, "TURN_ENDED"),
            RecoveredEvent(2, "TURN_BEGAN")
        };
        var spectatorReplayFrame = MatchReplayRedactor.BuildSpectatorFrame(
            "room-a",
            3,
            2,
            events.Select(recoveredEvent => recoveredEvent.Event).ToArray(),
            authoritativeState);
        var timing = spectatorReplayFrame.SpectatorSnapshot.Timing.ToDictionary(
            entry => entry.Key,
            entry => entry.Value,
            StringComparer.Ordinal);
        var continuousEffects = Assert.IsAssignableFrom<IEnumerable<object?>>(timing["continuousEffects"])
            .ToArray();
        Assert.Equal(2, continuousEffects.Length);
        var firstEffect = Assert.IsType<Dictionary<string, object?>>(continuousEffects[0])
            .ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        var secondEffect = Assert.IsType<Dictionary<string, object?>>(continuousEffects[1])
            .ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        Assert.Equal("effect-1", Assert.IsType<string>(firstEffect["effectId"]));
        Assert.Equal("effect-2", Assert.IsType<string>(secondEffect["effectId"]));
        Assert.Equal(1, Assert.IsType<int>(firstEffect["sequence"]));
        Assert.Equal(2, Assert.IsType<int>(secondEffect["sequence"]));
        Assert.Equal(2, Assert.IsType<int>(firstEffect["powerDelta"]));
        Assert.Equal(1, Assert.IsType<int>(secondEffect["powerDelta"]));
        Assert.Equal("SRC-001", Assert.IsType<string>(firstEffect["sourceCardNo"]));
        Assert.Equal("SRC-002", Assert.IsType<string>(secondEffect["sourceCardNo"]));

        secondEffect["effectId"] = "effect-1";
        continuousEffects[1] = secondEffect;
        timing["continuousEffects"] = continuousEffects;
        spectatorReplayFrame = spectatorReplayFrame with
        {
            SpectatorSnapshot = spectatorReplayFrame.SpectatorSnapshot with
            {
                Timing = timing
            }
        };

        var errors = MatchRecoveryValidator.Validate(
            "room-a",
            2,
            [],
            events,
            new Dictionary<string, RecoveredPlayerView>(StringComparer.Ordinal),
            authoritativeState,
            currentTick: 3,
            spectatorReplayFrame: spectatorReplayFrame);

        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing continuous effect item effect id effect-1 is duplicated",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing continuous effect item effect id effect-2 is required by authoritative state continuous effects",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing continuous effect item power delta does not match authoritative state continuous effect power delta for effect id effect-1",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing continuous effect item sequence does not match authoritative state continuous effect sequence for effect id effect-1",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing continuous effect item source card number does not match authoritative state continuous effect source card number for effect id effect-1",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing continuous effect ids disagree with authoritative state continuous effect ids",
                StringComparison.Ordinal));
        Assert.DoesNotContain(
            errors,
            error => error.Contains(
                "spectator replay frame timing continuous effect item effect id effect-1 is not present in authoritative state continuous effects",
                StringComparison.Ordinal));
        Assert.DoesNotContain(
            errors,
            error => error.Contains(
                "spectator replay frame timing continuous effect count",
                StringComparison.Ordinal));
    }

