                ["alice"] = PlayerZones.Empty with
                {
                    Battlefields = ["battlefield-1", "participant-1"]
                },
                ["bob"] = PlayerZones.Empty
            },
            cardObjects: new Dictionary<string, CardObjectState>(StringComparer.Ordinal)
            {
                ["battlefield-1"] = new(
                    "battlefield-1",
                    tags: [P6TokenFactoryCatalog.BattlefieldCardTag],
                    cardNo: "OGN·294/298",
                    ownerId: "alice",
                    controllerId: "alice"),
                ["participant-1"] = new(
                    "participant-1",
                    power: 4,
                    tags: [CardObjectTags.UnitCard],
                    ownerId: "alice",
                    controllerId: "alice")
            },
            objectLocations: new Dictionary<string, ObjectLocationState>(StringComparer.Ordinal)
            {
                ["battlefield-1"] = new("alice", "BATTLEFIELD", "battlefield-1"),
                ["participant-1"] = new("alice", "BATTLEFIELD", "battlefield-1")
            });
        var events = new[]
        {
            RecoveredEvent(1, "TURN_ENDED"),
            RecoveredEvent(2, "TURN_BEGAN")
        };
        var spectatorReplayFrame = MatchReplayRedactor.BuildSpectatorFrame(
            "room-a",
            3,
            2,
            events.Select(recoveredEvent => recoveredEvent.Event).ToArray(),
            authoritativeState);
        var timing = spectatorReplayFrame.SpectatorSnapshot.Timing.ToDictionary(
            entry => entry.Key,
            entry => entry.Value,
            StringComparer.Ordinal);
        var continuousEffects = Assert.IsAssignableFrom<IEnumerable<object?>>(timing["continuousEffects"])
            .ToList();
        Assert.Single(continuousEffects);
        var effect = Assert.IsType<Dictionary<string, object?>>(continuousEffects[0])
            .ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        var extraEffect = effect.ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);

        Assert.Equal("BATTLEFIELD", effect["scope"]);
        Assert.Equal("STATIC_AURA", effect["layer"]);
        Assert.Equal(
            "WHILE_SOURCE_BATTLEFIELD_AND_PARTICIPANT_AT_BATTLEFIELD",
            effect["duration"]);
        Assert.Equal("participant-1", effect["targetObjectId"]);
        Assert.False(effect.ContainsKey("requestedPowerDelta"));
        Assert.False(effect.ContainsKey("appliedPowerDelta"));
        Assert.False(effect.ContainsKey("minimumPower"));
        Assert.False(effect.ContainsKey("resultingPower"));
        Assert.False(effect.ContainsKey("appliedOrder"));
        effect["requestedPowerDelta"] = 1;
        effect["appliedPowerDelta"] = 1;
        effect["minimumPower"] = 0;
        effect["resultingPower"] = 5;
        effect["appliedOrder"] = 1;
        extraEffect["effectId"] = "effect-extra";
        extraEffect["sequence"] = 2;
        continuousEffects[0] = effect;
        continuousEffects.Add(extraEffect);
        timing["continuousEffects"] = continuousEffects.ToArray();
        spectatorReplayFrame = spectatorReplayFrame with
        {
            SpectatorSnapshot = spectatorReplayFrame.SpectatorSnapshot with
            {
                Timing = timing
            }
        };

        var errors = MatchRecoveryValidator.Validate(
            "room-a",
            2,
            [],
            events,
            new Dictionary<string, RecoveredPlayerView>(StringComparer.Ordinal),
            authoritativeState,
            currentTick: 3,
            spectatorReplayFrame: spectatorReplayFrame);

        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing continuous effect item static aura requested power delta must be absent",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing continuous effect item static aura applied power delta must be absent",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing continuous effect item static aura minimum power must be absent",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing continuous effect item static aura resulting power must be absent",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing continuous effect item static aura applied order must be absent",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing continuous effect item effect id effect-extra is not present in authoritative state continuous effects",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing continuous effect count 2 does not match authoritative state continuous effect count 1",
                StringComparison.Ordinal));
    }

