    [Fact]
    public void RecoveryValidatorRejectsSpectatorReplayTimingTriggerQueueMismatchWithoutCountMismatch()
    {
        const string battlefieldObjectId = "battlefield-a";
        const string visibleSourceObjectId = "visible-source-1";
        const string hiddenSourceObjectId = "hidden-source-1";
        var authoritativeState = new MatchState(
            "room-a",
            3,
            1,
            "alice",
            new Dictionary<string, string>(StringComparer.Ordinal)
            {
                ["alice"] = "P1",
                ["bob"] = "P2"
            },
            status: MatchStatuses.InProgress,
            readyPlayerIds: ["alice", "bob"],
            phase: MatchPhases.Main,
            timingState: TimingStates.NeutralOpen,
            playerZones: new Dictionary<string, PlayerZones>(StringComparer.Ordinal)
            {
                ["alice"] = PlayerZones.Empty with
                {
                    Base = [visibleSourceObjectId],
                    Battlefields = [battlefieldObjectId, hiddenSourceObjectId]
                },
                ["bob"] = PlayerZones.Empty
            },
            cardObjects: new Dictionary<string, CardObjectState>(StringComparer.Ordinal)
            {
                [battlefieldObjectId] = new(
                    battlefieldObjectId,
                    cardNo: "TEST-BATTLEFIELD",
                    ownerId: "alice",
                    controllerId: "alice",
                    tags: [P6TokenFactoryCatalog.BattlefieldCardTag]),
                [visibleSourceObjectId] = new(
                    visibleSourceObjectId,
                    ownerId: "alice",
                    controllerId: "alice"),
                [hiddenSourceObjectId] = new(
                    hiddenSourceObjectId,
                    power: 2,
                    isFaceDown: true,
                    ownerId: "alice",
                    controllerId: "alice",
                    tags: [CardObjectTags.UnitCard, CardObjectTags.Standby])
            },
            objectLocations: new Dictionary<string, ObjectLocationState>(StringComparer.Ordinal)
            {
                [battlefieldObjectId] = new("alice", "BATTLEFIELD", battlefieldObjectId),
                [visibleSourceObjectId] = new("alice", "BASE"),
                [hiddenSourceObjectId] = new("alice", "BATTLEFIELD", battlefieldObjectId)
            },
            triggerQueue:
            [
                new TriggerQueueItemState(
                    "trigger-visible",
                    "alice",
                    visibleSourceObjectId,
                    "LAST_BREATH",
                    "OBJECT_DESTROYED"),
                new TriggerQueueItemState(
                    "trigger-hidden",
                    "bob",
                    hiddenSourceObjectId,
                    "AMBUSH_REVEALED",
                    "BATTLEFIELD_HELD")
            ]);
        var events = new[]
        {
            RecoveredEvent(1, "TURN_ENDED"),
            RecoveredEvent(2, "TURN_BEGAN")
        };
        var spectatorReplayFrame = MatchReplayRedactor.BuildSpectatorFrame(
            "room-a",
            3,
            2,
            events.Select(recoveredEvent => recoveredEvent.Event).ToArray(),
            authoritativeState);
        var timing = spectatorReplayFrame.SpectatorSnapshot.Timing.ToDictionary(
            entry => entry.Key,
            entry => entry.Value,
            StringComparer.Ordinal);
        var triggerQueue = Assert.IsAssignableFrom<IEnumerable<object?>>(timing["triggerQueue"])
            .ToArray();
        var visibleTrigger = Assert.IsType<Dictionary<string, object?>>(triggerQueue[0])
            .ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        var hiddenTrigger = Assert.IsType<Dictionary<string, object?>>(triggerQueue[1])
            .ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        Assert.Equal(visibleSourceObjectId, Assert.IsType<string>(visibleTrigger["sourceObjectId"]));
        Assert.Equal("VISIBLE", Assert.IsType<string>(visibleTrigger["sourceVisibility"]));
        Assert.Equal("HIDDEN", Assert.IsType<string>(hiddenTrigger["sourceObjectId"]));
        Assert.Equal("HIDDEN", Assert.IsType<string>(hiddenTrigger["sourceVisibility"]));
        Assert.Equal("HIDDEN", Assert.IsType<string>(hiddenTrigger["effectKind"]));

        visibleTrigger["triggerId"] = "wrong-trigger";
        visibleTrigger["controllerId"] = "bob";
        visibleTrigger["sourceObjectId"] = "wrong-source";
        visibleTrigger["effectKind"] = "WRONG_EFFECT";
        visibleTrigger["triggeredByEventKind"] = "WRONG_EVENT";
        hiddenTrigger["sourceVisibility"] = "VISIBLE";
        triggerQueue[0] = visibleTrigger;
        triggerQueue[1] = hiddenTrigger;
        timing["triggerQueue"] = triggerQueue;
        spectatorReplayFrame = spectatorReplayFrame with
        {
            SpectatorSnapshot = spectatorReplayFrame.SpectatorSnapshot with
            {
                Timing = timing
            }
        };

        var errors = MatchRecoveryValidator.Validate(
            "room-a",
            2,
            [],
            events,
            new Dictionary<string, RecoveredPlayerView>(StringComparer.Ordinal),
            authoritativeState,
            currentTick: 3,
            spectatorReplayFrame: spectatorReplayFrame);

        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing trigger queue ids disagree with authoritative state trigger queue ids; expected [trigger-visible, trigger-hidden] but got [wrong-trigger, trigger-hidden]",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing trigger queue controller ids disagree with authoritative state trigger queue controller ids; expected [alice, bob] but got [bob, bob]",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing trigger queue source object ids disagree with authoritative state trigger queue source object ids; expected [visible-source-1, HIDDEN] but got [wrong-source, HIDDEN]",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing trigger queue source visibilities disagree with authoritative state trigger queue source visibilities; expected [VISIBLE, HIDDEN] but got [VISIBLE, VISIBLE]",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing trigger queue effect kinds disagree with authoritative state trigger queue effect kinds; expected [LAST_BREATH, HIDDEN] but got [WRONG_EFFECT, HIDDEN]",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing trigger queue triggered event kinds disagree with authoritative state trigger queue triggered event kinds; expected [OBJECT_DESTROYED, BATTLEFIELD_HELD] but got [WRONG_EVENT, BATTLEFIELD_HELD]",
                StringComparison.Ordinal));
        Assert.DoesNotContain(
            errors,
            error => error.Contains(
                "spectator replay frame timing trigger queue count",
                StringComparison.Ordinal));
    }

