            currentTick: 3,
            spectatorReplayFrame: spectatorReplayFrame);

        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing trigger queue item trigger id trigger-extra-a is not present in authoritative state trigger queue",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing trigger queue item trigger id trigger-extra-b is not present in authoritative state trigger queue",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing trigger queue item trigger id trigger-hidden is required by authoritative state trigger queue",
                StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains(
                "spectator replay frame timing trigger queue count 3 does not match authoritative state trigger queue count 2",
                StringComparison.Ordinal));
    }

