            authoritativeState,
            currentTick: 3,
            spectatorReplayFrame: spectatorReplayFrame);

        Assert.Contains(
            errors,
            error => error.Contains("spectator replay frame timing battle damage assignment damage pool property attacker-a appears more than once", StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains("spectator replay frame timing battle damage assignment damage pool property defender-a has surrounding whitespace", StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains("spectator replay frame timing battle damage assignment damage pool property name is required", StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains("spectator replay frame timing battle damage assignment legal targets property attacker-a appears more than once", StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains("spectator replay frame timing battle damage assignment legal targets property defender-a has surrounding whitespace", StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains("spectator replay frame timing battle damage assignment legal targets property name is required", StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains("spectator replay frame timing battle damage assignment existing damage property defender-a appears more than once", StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains("spectator replay frame timing battle damage assignment existing damage property attacker-a has surrounding whitespace", StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains("spectator replay frame timing battle damage assignment existing damage property name is required", StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains("spectator replay frame timing battle damage assignment lethal damage threshold property defender-a appears more than once", StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains("spectator replay frame timing battle damage assignment lethal damage threshold property attacker-a has surrounding whitespace", StringComparison.Ordinal));
        Assert.Contains(
            errors,
            error => error.Contains("spectator replay frame timing battle damage assignment lethal damage threshold property name is required", StringComparison.Ordinal));
    }

